   $tpl${"version":1,"document_id":"pov","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":null,"footer":null,"font_default":{"family":"Calibri","size":11},"line_spacing":1.15,"max_pages":null,"max_slides":null},"nodes":[{"id":"ov-001","type":"heading","content":{"level":1,"text":"RFP Pipeline"},"style":{"color":"#1a1816"},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-002","type":"text_block","content":{"text":"AI-Powered Proposal Management for Government Contractors"},"style":{"color":"#d44432","weight":"bold","size":15},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-003","type":"text_block","content":{"text":"PLATFORM OVERVIEW · CAPABILITIES · APPLY · CURATE · DRAFT · WIN"},"style":{"color":"#7a6d5e","size":9},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-004","type":"divider","content":{"color":"#d44432","thickness":2,"line_style":"solid"},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":false},{"id":"ov-005","type":"text_block","content":{"text":"Win non-dilutive federal R&D funding — without burning a month of payroll on every submission. RFP Pipeline pairs 25 years of hands-on expertise with isolated, company-specific AI, so you pursue more opportunities and submit better proposals. Purpose-built for SBIR, STTR, BAA, OTA, CSO, and grants — it carries you from a ranked opportunity to a submission-ready package in one connected workspace, with every step tracked and every AI action reviewed and approved by your team."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-006","type":"table","content":{"headers":["Federal Sources","Expert-Review SLA","Years Fed R&D","Human-Gated AI"],"rows":[["4+","72 hours","25+","100%"]],"header_style":{"bold":true,"bg":"#1a1816"},"border_style":"single"},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-007","type":"heading","content":{"level":2,"text":"Why RFP Pipeline — the opportunity & the economics"},"style":{"color":"#1a1816"},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-008","type":"text_block","content":{"text":"There are billions each year in non-dilutive federal R&D funding — grant-like money you keep your equity and IP on. Most qualifying small businesses never apply, because the process is opaque, deadline-driven, and expensive to chase. RFP Pipeline makes it accessible."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-009","type":"callout","content":{"variant":"success","title":"Keep your equity and your IP.","text":"Non-dilutive awards fund your R&D without giving up ownership — the cheapest capital a technical small business will ever raise."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-010","type":"text_block","content":{"text":"The old way is expensive and slow — usually a monitoring subscription, an outside consultant, and a month of payroll on every submission:"},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-011","type":"table","content":{"headers":["The status quo","What it costs you","RFP Pipeline"],"rows":[["Opportunity monitoring service","~$5,000 / month for a feed you still triage","Included"],["Proposal consultant","Commonly ~10% of the award as a success fee","Flat fee, no success fee"],["Your team's time","A month of payroll per submission, from scratch","Draft from your library"]],"header_style":{"bold":true,"bg":"#1a1816"},"border_style":"single"},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-012","type":"callout","content":{"variant":"info","title":"The math.","text":"RFP Pipeline replaces a $5,000/mo monitoring service and a 10%-of-award consultant — for $499/mo and a flat per-proposal fee. No success fee, ever."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-013","type":"heading","content":{"level":2,"text":"How it works — the pursuit lifecycle"},"style":{"color":"#1a1816"},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-014","type":"numbered_list","content":{"items":[{"text":"Apply — daily, expert-curated ingestion across SAM.gov, SBIR.gov, Grants.gov, and agency portals, ranked to your tech areas. Pin a fit, open a proposal portal."},{"text":"Curate — within a 72-hour SLA, an RFP expert provisions your build: the compliance matrix, required volumes, and section molds from the actual solicitation."},{"text":"Draft — your isolated, company-specific AI drafts every section from your library; your team revises in a stage-gated workspace with a live compliance matrix. AI is advisory."},{"text":"Win — export a compliant, submission-ready package. Record the outcome; a win starts your contract and feeds your library so winning content ranks higher next time."}]},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-015","type":"callout","content":{"variant":"note","title":"A compounding advantage.","text":"Because everything you draft is captured to your library with lineage, your second proposal is faster than your first — and your tenth is faster than your second."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-016","type":"heading","content":{"level":2,"text":"Discover & prioritize"},"style":{"color":"#1a1816"},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-017","type":"text_block","content":{"text":"Opportunity discovery & your ranked pipeline. Every federal opportunity lands on your Opportunity Pipeline, ranked for you, with agency, program type, close date, and a live submission-stage badge. Daily ingestion; AI ranks against your profile; deadline alerts fire before the clock runs out; pin to copy documents into your workspace."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-018","type":"text_block","content":{"text":"Scoring buckets — rank by your strategy. Define scoring buckets from keywords, agencies, program types, and NAICS codes. Transparent, per-factor scoring you can inspect; edit a bucket and the pipeline re-ranks instantly."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-019","type":"text_block","content":{"text":"Deadline & amendment awareness. Submission-stage badges and due dates on every card; an update-available strip when the agency revises a solicitation; alerts on your dashboard and notification bell."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-020","type":"heading","content":{"level":2,"text":"Expert curation & isolated AI"},"style":{"color":"#1a1816"},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-021","type":"text_block","content":{"text":"Expert-curated proposal workspaces. A real expert reads the solicitation and builds the skeleton within a 72-hour SLA; provisioning instantiates the compliance matrix + volume molds; a running Ask-the-Expert allowance covers the judgment calls AI cannot make."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-022","type":"text_block","content":{"text":"Your isolated, company-specific AI. Your AI is walled to your company: per-company isolation at the data layer, no model training on your content, structured memory grounding drafts in your prior work, and untrusted external content fenced away from the AI."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-023","type":"text_block","content":{"text":"Compliance built in from the first draft. Requirements are extracted into a live matrix; an AI compliance pass scores your proposal and flags gaps before an evaluator would; page-fill gauges track you against the agency limits."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-024","type":"heading","content":{"level":2,"text":"Your library & workspace"},"style":{"color":"#1a1816"},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-025","type":"text_block","content":{"text":"A reusable content library that compounds. Upload → auto-atomize → tag → reuse; capture content from any screen one-way; templify a past winning proposal. Your content is copied forward into each proposal, so retiring an item never disturbs a proposal already built from it."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-026","type":"text_block","content":{"text":"The proposal workspace & compliance matrix. A volume-and-section matrix, a stage-control bar with gate requirements, per-section accept-and-lock, and page-fill gauges. When a volume is fully locked its downloads light up; the live compliance matrix advances with every lock."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-027","type":"text_block","content":{"text":"Templates, versioning & a full audit trail. Save any proposal structure as a reusable skeleton; per-section version history with restore; every action posts to an audit trail."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-028","type":"heading","content":{"level":2,"text":"The AI workforce"},"style":{"color":"#1a1816"},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-029","type":"text_block","content":{"text":"An AI workforce works your proposal alongside your team — always advisory, always landing in review for your approval. It never submits, locks, or advances a stage on its own, and it is governed by budget, rate, and per-run cost caps you set."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-030","type":"bulleted_list","content":{"items":[{"text":"Proposal Studio — three gated loops (Draft, Refine, Compliance); review, comment, and approve at each gate, or run all three automatically."},{"text":"AI drafting & full-draft modes — first-draft empty sections, or the whole proposal in one pass (guided, restyle, or full-auto), in the voice you choose."},{"text":"Color-team review — a red/gold-team pass posting section-level recommendations into each thread."},{"text":"Compliance check — scores the proposal against the requirements, pass/fail/partial per item."},{"text":"Research scout — market research, prior art, and the competitor landscape into a cited brief (web results treated as untrusted data)."},{"text":"Cost model — assembles your cost volume with live formulas."}]},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-031","type":"callout","content":{"variant":"info","title":"Advisory by design.","text":"Every AI output lands in review, redlined and reversible. Your team is the gate; the AI never advances past it on its own."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-032","type":"heading","content":{"level":2,"text":"Collaborate, deliver & win"},"style":{"color":"#1a1816"},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-033","type":"text_block","content":{"text":"Team & partner collaboration. Invite teammates and external partners with per-section, per-permission access (view / comment / edit). Segregated collaboration spaces wall off partner content; every contribution is attributed; deactivating a member revokes access instantly while keeping their history."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-034","type":"text_block","content":{"text":"Submission-ready deliverables. Export as Word, PDF, Excel (cost volumes with live formulas), or a per-volume ZIP — submission-formatted, figures and tables native, sections in true document order. A packaging review checks volume completeness, required forms, and format before you submit."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-035","type":"text_block","content":{"text":"Outcome & contract — the flywheel. Record Won / Lost / Withdrawn; a win instantiates a contract + kickoff; outcome signals re-weight your library so the platform gets sharper the more you use it."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-036","type":"heading","content":{"level":2,"text":"Built for trust & control"},"style":{"color":"#1a1816"},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-037","type":"bulleted_list","content":{"items":[{"text":"Isolated, company-specific AI — walled to your company; your context never crosses to another customer."},{"text":"No model training on your data — your proposals and library serve you, never a shared model."},{"text":"Multi-tenant isolation — your workspace, library, and proposals are structurally yours alone."},{"text":"Full audit trail — every action, by every person and every AI, is logged and traceable end to end."},{"text":"AI is advisory & human-gated — it proposes; your team approves. It never auto-writes, submits, or locks."},{"text":"Governed AI — budget, rate, and per-run cost caps keep AI usage predictable and under your control."},{"text":"Injection-fenced — untrusted external content is treated as data, never instructions the AI will follow."}]},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-038","type":"callout","content":{"variant":"success","title":"Proven, not theoretical.","text":"The end-to-end flow — discover, curate, draft, comply, export, win — has been verified on real DoD SBIR builds, including a NAVAIR/NAVSEA counter-UAS topic, from a ranked opportunity to a submission-ready, downloadable package."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-039","type":"heading","content":{"level":2,"text":"Plans & who does what"},"style":{"color":"#1a1816"},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-040","type":"table","content":{"headers":["Plan","Price","What is included"],"rows":[["Spotlight Subscription (required, monthly)","$499 / mo","Daily ingestion; AI ranking; expert-curated compliance matrix; deadline alerts; 15 min Ask-the-Expert/mo (rolls over). Required to purchase any portal; 3-month minimum."],["Phase I — Like Effort (per proposal)","$1,999 ea","SBIR/STTR Phase I, smaller BAA, OTA/CSO short-form. 72-hour expert curation. Stage-gated workspace. Custom AI drafting."],["Phase II — Like Effort (per proposal)","$4,999 ea","SBIR/STTR Phase II, larger BAA, OTA prototypes, complex NOFOs. 20-50+ page tech volumes. Commercialization plans. $3,999 with a linked Phase I."]],"header_style":{"bold":true,"bg":"#1a1816"},"border_style":"single"},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-041","type":"text_block","content":{"text":"No success fee, ever. Flat, predictable pricing that replaces a $5,000/mo monitoring service and a 10%-of-award consultant."},"style":{"color":"#7a6d5e","size":10},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-042","type":"table","content":{"headers":["Role","What they do"],"rows":[["Company Admin","Runs the company workspace — opens pursuits, invites the team, and drives the build from opportunity to submission."],["Team Member","Contributes to assigned proposals and sections, within the access their admin grants."],["External Partner","Stage-scoped access to a specific proposal — view, comment, or edit only where invited."],["RFP Pipeline Expert","Curates the solicitation and provisions your build behind the scenes, so you start on-structure."]],"header_style":{"bold":true,"bg":"#1a1816"},"border_style":"single"},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true},{"id":"ov-043","type":"divider","content":{"color":"#d44432","thickness":2,"line_style":"solid"},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":false},{"id":"ov-044","type":"callout","content":{"variant":"success","title":"From opportunity to award","text":"From a ranked opportunity to a submission-ready, compliant proposal — RFP Pipeline gives government contractors an AI-accelerated pursuit process, with your team in control at every gate. Book a walkthrough on one of your own target opportunities, or apply for the Founding Cohort."},"style":{},"provenance":{"source":"manual","drafted_by":"00000000-0000-4000-8000-000000000000","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[{"actor_id":"00000000-0000-4000-8000-000000000000","actor_name":"RFP Pipeline","action":"created","timestamp":"2026-08-04T00:00:00.000Z"}],"library_eligible":true}],"metadata":{"title":"","created_at":"2026-08-04T00:00:00.000Z","last_modified_at":"2026-08-04T00:00:00.000Z","version_number":1,"status":"empty"}}$tpl$::jsonb),
