   $tpl${"version":1,"document_id":"cut","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":null,"footer":null,"font_default":{"family":"Calibri","size":11},"line_spacing":1.15,"max_pages":null,"max_slides":null},"nodes":[{"id":"tpl-cut-01","type":"heading","content":{"level":1,"text":"RFP Pipeline — Platform Cut Sheet"},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-02","type":"text_block","content":{"text":"AI + Expert · From Application to Submission. A proposal engine, not a proposal gamble."},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-03","type":"text_block","content":{"text":"Win non-dilutive federal R&D funding — without burning a month of payroll on every submission. 25 years of hands-on expertise + isolated, company-specific AI. SBIR · STTR · BAA · OTA · CSO · Grants."},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-04","type":"table","content":{"headers":["Federal Sources","Expert-Review SLA","Years Fed R&D","Human-Gated AI"],"rows":[["4+","72 hours","25+","100%"]],"header_style":{"bold":true},"border_style":"single"},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-05","type":"heading","content":{"level":2,"text":"The economics"},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-06","type":"table","content":{"headers":["The status quo","What it costs you","RFP Pipeline"],"rows":[["Opportunity monitoring","~$5,000 / month for a feed you still triage","Included"],["Proposal consultant","Commonly ~10% of the award as a success fee","Flat fee, no success fee"],["Your team’s time","A month of payroll per submission, from scratch","Draft from your library"]],"header_style":{"bold":true},"border_style":"single"},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-07","type":"text_block","content":{"text":"The math: replaces a $5,000/mo monitoring service and a 10%-of-award consultant — for $499/mo and a flat per-proposal fee. No success fee, ever."},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-08","type":"heading","content":{"level":2,"text":"The platform at a glance"},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-09","type":"bulleted_list","content":{"items":[{"text":"Discovery & ranked pipeline — daily ingestion across SAM.gov, SBIR.gov, Grants.gov & agency portals, ranked to your tech areas."},{"text":"Scoring buckets — rank the whole pipeline by your own keywords, agencies, program types & NAICS."},{"text":"Expert curation (72h SLA) — a real expert provisions your compliance matrix, volumes & section molds."},{"text":"Isolated, company-specific AI — walled to your company; no model training on your data; injection-fenced."},{"text":"Reusable content library — upload → atomize → reuse; copied forward into every proposal."},{"text":"Workspace & compliance matrix — stage-gated build, per-section lock, live requirement coverage."},{"text":"Proposal Studio — Draft → Refine → Compliance, gated; you approve at each step."},{"text":"AI review & compliance check — color-team recommendations + pass/fail requirement scoring."},{"text":"Submission-ready exports — Word, PDF, Excel & per-volume ZIP + a packaging-completeness review."},{"text":"Outcome → contract — a win starts your contract + kickoff; every result sharpens your library."}]},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-10","type":"heading","content":{"level":2,"text":"Pricing"},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-11","type":"table","content":{"headers":["Plan","Price","Included"],"rows":[["Spotlight Subscription (monthly)","$499 / mo","Daily ingestion, AI ranking, expert-curated compliance matrix, deadline alerts. Required to buy any portal."],["Phase I — Like Effort","$1,999 ea","SBIR/STTR Phase I, smaller BAA, OTA/CSO short-form. 72-hour expert curation."],["Phase II — Like Effort","$4,999 ea","SBIR/STTR Phase II, larger BAA, OTA prototypes, complex NOFOs. $3,999 with a linked Phase I."]],"header_style":{"bold":true},"border_style":"single"},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true},{"id":"tpl-cut-12","type":"text_block","content":{"text":"Trust & control: multi-tenant isolation · no model training · full audit trail · AI advisory & human-gated · injection-fenced · governed AI (budget/rate caps). Book a walkthrough, or apply for the Founding Cohort. Platform launches August 2026."},"style":{},"provenance":{"source":"template","drafted_at":"2026-08-04T00:00:00.000Z"},"history":[],"library_eligible":true}],"metadata":{"title":"","created_at":"2026-08-04T00:00:00.000Z","last_modified_at":"2026-08-04T00:00:00.000Z","version_number":1,"status":"empty"}}$tpl$::jsonb)
